void swap(int *p1, int *p2) {
    int p = *p1;
    *p1 = *p2;
    *p2 = p;
}

void min_first(int size, int data[size]) {
    int min = data[0];
    int i = 0;
    int index = 0;
    for (int i = 0; i < size; i++) {
        if (min > data[i]) {
            min = data[i];
            index = i;
        }
    }
    swap(&data[index], &data[0]);
}

